32	// SemVer represents a semantic version.
33	type SemVer struct {
34		Major      int
35		Minor      int
36		Patch      int
37		PreRelease string // e.g., "rc1", "beta2"
38	}
39	
40	// ParseSemVer parses a version string like "v0.0.8" or "1.2.3-beta".
41	// Returns error for non-semantic versions like "dev".
42	func ParseSemVer(v string) (SemVer, error) {
43		// Handle special cases
44		if v == "dev" || v == "" {
45			return SemVer{}, fmt.Errorf("non-semantic version: %s", v)
46		}
47	
48		v = strings.TrimPrefix(v, "v")
49	
50		// Split by '-' for pre-release
51		parts := strings.SplitN(v, "-", 2)
52		versionStr := parts[0]
53		prerelease := ""
54		if len(parts) > 1 {
55			prerelease = parts[1]
56		}
57	
58		// Parse major.minor.patch
59		nums := strings.Split(versionStr, ".")
60		if len(nums) != 3 {
61			return SemVer{}, fmt.Errorf("invalid version format: %s", v)
62		}
63	
64		var major, minor, patch int
65		if _, err := fmt.Sscanf(nums[0], "%d", &major); err != nil {
66			return SemVer{}, fmt.Errorf("invalid version number: %s", v)
67		}
68		if _, err := fmt.Sscanf(nums[1], "%d", &minor); err != nil {
69			return SemVer{}, fmt.Errorf("invalid version number: %s", v)
70		}
71		if _, err := fmt.Sscanf(nums[2], "%d", &patch); err != nil {
72			return SemVer{}, fmt.Errorf("invalid version number: %s", v)
73		}
74	
75		return SemVer{Major: major, Minor: minor, Patch: patch, PreRelease: prerelease}, nil
76	}
77	
78	// String returns the version string.
79	func (v SemVer) String() string {
80		s := fmt.Sprintf("v%d.%d.%d", v.Major, v.Minor, v.Patch)
81		if v.PreRelease != "" {
82			s += "-" + v.PreRelease
83		}
84		return s
85	}
86	
87	// Less returns true if v < other.
88	func (v SemVer) Less(other SemVer) bool {
89		if v.Major != other.Major {
90			return v.Major < other.Major
91		}
92		if v.Minor != other.Minor {
93			return v.Minor < other.Minor
94		}
95		// Pre-release versions are less than release versions
96		if v.PreRelease != "" && other.PreRelease == "" {
97			return true
98		}
99		if v.PreRelease == "" && other.PreRelease != "" {
100			return false
101		}
102		return v.Patch < other.Patch || (v.Patch == other.Patch && v.PreRelease < other.PreRelease)
103	}
