294	// ReplaceBinary atomically replaces the old binary with the new one.
295	func ReplaceBinary(oldPath, newPath string, w io.Writer) error {
296		fmt.Fprintf(w, "Replacing binary at %s...\n", oldPath)
297	
298		// Get current permissions and owner
299		info, err := os.Stat(oldPath)
300		if err != nil {
301			return fmt.Errorf("checking original binary: %w", err)
302		}
303	
304		// Atomic rename (works on same filesystem)
305		if err := os.Rename(newPath, oldPath); err != nil {
306			// If rename fails (different filesystem), try copy+remove
307			fmt.Fprintf(w, "  Note: Using fallback copy method...\n")
308	
309			// Read new binary
310			data, readErr := safefs.ReadFile(newPath)
311			if readErr != nil {
312				_ = safefs.Remove(newPath)
313				return fmt.Errorf("reading new binary: %w", readErr)
314			}
315	
316			// Write to old path (atomic on most systems for small files)
317			writeErr := safefs.WriteFile(oldPath, data, info.Mode())
318			if writeErr != nil {
319				_ = safefs.Remove(newPath)
320				return fmt.Errorf("writing new binary: %w", writeErr)
321			}
322	
323			// Clean up temp file
324			_ = safefs.Remove(newPath)
325		}
326	
327		// Preserve prior permission bits.
328		if err := safefs.Chmod(oldPath, info.Mode()); err != nil {
329			return fmt.Errorf("restoring original permissions: %w", err)
330		}
331	
332		fmt.Fprintf(w, "Successfully updated ddx-agent\n")
333		return nil
334	}
