113	// GetLatestRelease fetches the latest release from GitHub API.
114	func GetLatestRelease(repo string, cacheFile string) (*GitHubRelease, error) {
115		// Check cache first
116		if cached, err := loadCachedVersion(cacheFile); err == nil && time.Since(cached.Time) < updateCheckTTL {
117			return &GitHubRelease{TagName: cached.Version}, nil
118		}
119	
120		url := fmt.Sprintf("%s/repos/%s/releases/latest", strings.TrimRight(githubAPIBase, "/"), repo)
121		client := &http.Client{Timeout: 10 * time.Second}
122		resp, err := client.Get(url)
123		if err != nil {
124			return nil, fmt.Errorf("fetching latest release: %w", err)
125		}
126		defer resp.Body.Close()
127	
128		if resp.StatusCode != http.StatusOK {
129			body, _ := io.ReadAll(resp.Body)
130			return nil, fmt.Errorf("GitHub API returned %s: %s", resp.Status, string(body))
131		}
132	
133		var release GitHubRelease
134		if err := json.NewDecoder(resp.Body).Decode(&release); err != nil {
135			return nil, fmt.Errorf("parsing release data: %w", err)
136		}
137	
138		// Cache the result
139		if err := saveCachedVersion(cacheFile, release.TagName); err != nil {
140			return nil, err
141		}
142	
143		return &release, nil
144	}
