175	// FindBinaryPath finds the path to the agent binary.
176	func FindBinaryPath() (string, error) {
177		exe, err := os.Executable()
178		if err != nil {
179			return "", fmt.Errorf("getting executable path: %w", err)
180		}
181	
182		dir := filepath.Dir(exe)
183		// Check if in common locations
184		if strings.Contains(dir, ".local/bin") ||
185			strings.Contains(dir, "go/bin") ||
186			strings.Contains(dir, "/bin/") {
187			return exe, nil
188		}
189	
190		path, err := exec.LookPath(productinfo.BinaryName)
191		if err != nil || path == "" {
192			return exe, nil // Return current executable as fallback
193		}
194		return path, nil
195	}
