294	// ReplaceBinary atomically replaces the old binary with the new one.
295	func ReplaceBinary(oldPath, newPath string, w io.Writer) error {
296		fmt.Fprintf(w, "Replacing binary at %s...\n", oldPath)
297	
298		// Get current permissions and owner
299		info, err := os.Stat(oldPath)
300		if err != nil {
301			return fmt.Errorf("checking original binary: %w", err)
302		}
303	
304		// Atomic rename (works on same filesystem)
